diffs.to:
/* Opt-in proof of deployment: regular visitors see no marker. */
html[data-tc-release-preview="1"] body::before {
  content: "Trabajo Cerca | version de prueba TC-20261121-A";
  position: fixed;
  left: 50%;
  bottom: max(10px, env(safe-area-inset-bottom));
  transform: translateX(-50%);
  z-index: 2147483000;
  max-width: calc(100vw - 20px);
  box-sizing: border-box;
  border-radius: 8px;
  padding: 9px 12px;
  background: #133b2d;
  color: #ffffff;
  font: 700 12px/1.35 system-ui, sans-serif;
  text-align: center;
  overflow-wrap: anywhere;
  box-shadow: 0 3px 12px #0004;
  pointer-events: none;
}
